/*eslint-disable*/import type{Messages}from"@lingui/core";export const messages=JSON.parse("{\"-C4dIk\":[\"Sudokun som kräver en tvingande kedja är sällsynta och dyra att söka fram på begäran, så Suuudokuuu levereras med ett inbyggt urval som redan har kontrollerats av en exakt täckningslösare med Dancing Links och en bitmasklösare, bedömts och filtrerats till sudokun med tvingande kedjor innan det packas.\"],\"-Elizp\":[\"När skärningar börjar kännas automatiska, gå upp till <0>häftet med svårt sudoku att skriva ut</0> för fisk- och wing-mönster. Backa till <1>lätt sudoku att skriva ut</1> för en uppvärmning med enbart singlar, eller spela Medel på skärmen på <2>sidan för medelsvår sudoku</2>.\"],\"-bYKwe\":[\"Innehåller Everest (SE 11.9), Platinum Blonde (SE 10.9) och AI Escargot (SE 10.6).\"],\"-iJ7nh\":[[\"clueCount\"],\" givna siffror av 81 rutor, går att lösa enbart med sista lediga rutan och nakna singlar.\"],\"-vAdwL\":[\"Tekniker\"],\"0Ktk6B\":[\"Uppdaterad <0>\",[\"formattedDate\"],\"</0>\"],\"0L9JZJ\":[\"Hur många sudokun finns i PDF:en med lätt sudoku att skriva ut?\"],\"0MRfHz\":[\"Oändlighet-sudoku\"],\"0RoXsf\":[\"Är PDF:en med sudoku på nivån Mardröm att skriva ut gratis?\"],\"0Sy9Gs\":[\"Hur många sudokun finns i PDF:en med sudoku på nivån Helvete att skriva ut?\"],\"0bpi83\":[\"Sudokuhäften att skriva ut efter svårighetsgrad\"],\"0r_rbI\":[\"Har \",[\"SITE_NAME\"],\" reklam?\"],\"0zmlwH\":[\"Ladda ner \",[\"title\"],\" (PDF)\"],\"18cwop\":[\"<0>Lätt</0> – \",[\"easyClueCount\"],\" givna siffror, garanterat med minst en dold singel och aldrig mer än så.\"],\"1KnfS2\":[\"Hur många givna siffror har ett sudoku på nivån Mardröm?\"],\"1Lvcgc\":[\"Sudoku 1 från häftet Mardröm, ett av \",[\"PRINTABLE_BOOKLET_SIZE\"],\" i PDF:en.\"],\"1SEI1B\":[\"Det är Suuudokuuus svåraste genererade nivå, uppmätt till SE \",[\"seRatingRange\"],\" i ett urval på \",[\"sampleSize\"],\" sudokun. Varje sudoku kräver kedje- eller färgläggningslogik ovanpå de fisk- och wing-mönster som Svår redan kräver.\"],\"1ZWQlV\":[\"Så skriver du ut sudokuna\"],\"1ZluOW\":[\"Därför hjälper papper med kedjor\"],\"1aVkEA\":[\"En skärningsteknik arbetar med överlappningen mellan ett block och en rad eller kolumn. Ett pekande par eller en pekande trippel hittar en siffra som är begränsad till två eller tre rutor i ett block som alla delar en linje, och stryker den från resten av linjen. Block-rad-reduktion är spegelbilden, som arbetar från en linje tillbaka in i ett block. Nakna och dolda par är ingången till resonemang om delmängder: två rutor som delar exakt två kandidater, eller två siffror som passar i exakt två rutor i en enhet, låser i båda fallen de två rutorna från allt annat i enheten. Inget av detta placerar en siffra direkt – det tar bara bort kandidater – men vid \",[\"clueCount\"],\" givna siffror har ett medelsvårt sudoku alltid minst ett sådant mönster som väntar, och det räcker oftast för att öppna för en ny naken singel ett eller två drag senare. Nivån är begränsad även åt andra hållet: ingenting i den kräver någonsin en fisk, en wing eller en kedja, eftersom ett sudoku som gör det flyttas upp till Svår i stället.\"],\"27Qok0\":[\"Inget på nivån kräver någonsin en fisk, en wing eller en kedja – ett sudoku som gör det flyttas upp till Svår i stället.\"],\"2Dg4GX\":[\"Hur svårt är det, ärligt talat\"],\"2Lb_CG\":[\"Leta efter dolda singlar\"],\"2N-XHb\":[\"Sudoku för seniorer\"],\"2gnUkr\":[\"Nybörjare\"],\"2wuXBd\":[\"Det allra första du ska kontrollera är om ett block, en rad eller en kolumn bara saknar en siffra. Om åtta av de nio rutorna i en enhet redan är ifyllda måste den nionde rutan få den siffra som enheten fortfarande saknar – inga kandidater att jämföra, bara subtraktion.\"],\"3-aLmy\":[\"Ja. Båda finns i uppsättningen Oändlighet, tillsammans med Platinum Blonde och Golden Nugget. Varje spel blandar om siffror, rader och kolumner, så rutnätet ser olika ut varje gång medan sudokut förblir detsamma.\"],\"35wRk8\":[\"Det är den lättaste nivån Suuudokuuu erbjuder, och generatorn garanterar det: ett sudoku levereras som Nybörjare först när en lösare som är begränsad till sista lediga rutan och nakna singlar har avslutat det. Vårt urval mäter SE \",[\"seRatingRange\"],\", utan kandidatspårning och utan risk för tvingande gissningar.\"],\"367Cn7\":[\"Vilken teknik kräver ett häfte med lätt sudoku?\"],\"3DJmkH\":[\"Vår teknikmotor håller med om att de här sudokuna ligger bortom dess räckvidd. Den kan varje mönster i <0>teknikindexet</0>, upp till <1/> och <2/>, och klarar ändå inte av att avsluta ett enda sudoku på Oändlighet på egen hand. Det betyder inte att de kräver gissning; det betyder att de kräver längre tvingande nät än motorn implementerar. Ledtrådar är avstängda som standard på Mardröm, Helvete och Oändlighet, och en inställning slår på dem igen om du vill ha motorns hjälp så långt den räcker.\"],\"3SwmIF\":[\"När du startar ett spel på Oändlighet väljer appen ett av de sudokuna och maskerar det. Den byter beteckning på siffrorna, blandar rader inom sina band, kolumner inom sina stackar samt banden och stackarna själva, och speglar ibland rutnätet över dess diagonal. Inget av det ändrar logiken eller bedömningen, så den Everest du spelar är fortfarande Everest, den ser bara inte ut som bilden nedan.\"],\"3a3AKD\":[\"Är det här häftet med sudoku för nybörjare att skriva ut gratis?\"],\"3c-rtT\":[\"Ladda ner på App Store\"],\"3l9jCt\":[\"Hur många svårighetsnivåer för sudoku har Suuudokuuu?\"],\"3m4lq2\":[\"En fisk är lätt att missa på en skärm där bara en handfull rutor syns åt gången, eftersom mönstret ligger i var en siffra kan stå över två, tre eller fyra hela linjer samtidigt. På ett helt utskrivet rutnät kan du markera siffrans återstående platser nedåt i en kolumn och läsa av formen direkt på sidan. Wings kräver det motsatta perspektivet – några bivalenta rutor som ser varandra över rutnätet – och om du ringar in dem med blyerts blir överlappningen uppenbar. Eftersom båda familjerna är lätta att tillämpa fel de första gångerna är det värt att kontrollera sitt arbete mot lösningssidorna längst bak varje gång, tills formen sitter i ryggraden.\"],\"4-X0DJ\":[\"Hämta på Google Play\"],\"4DuWbm\":[\"<0>Radregeln.</0> Var och en av de nio raderna ska innehålla siffrorna 1 till 9 exakt en gång vardera.\"],\"4EAgIb\":[\"Tomt sudokurutnät\"],\"4HAVnv\":[\"Varje sudoku i det här häftet kommer från ett inbyggt urval som Suuudokuuu kontrollerar med två oberoende lösningsalgoritmer – en exakt täckningslösare med Dancing Links och en bitmasklösare med typade arrayer – innan det levereras, så varje rutnät bekräftas ha exakt en lösning. Urvalet hämtar från tdokuprojektets katalog med 17 givna siffror och från magictours lista top1465 med svåra sudokun, och varje sudoku löses dessutom logiskt och bedöms på SE-skalan när urvalet packas. Bara sudokun vars svåraste steg är en tvingande kedja överlever; allt som faller för en kedja, färgläggning eller AIC kasseras, eftersom varken antalet givna siffror eller källistan ensam räcker för att lova ett sudoku på Helvete. Varje överlevare går ändå att lösa med våra tekniksteg utan att gissa, så varje sudoku här är garanterat lösbart med logik innan du tar upp en blyertspenna.\"],\"4NMPvd\":[\"Vilka tekniker behöver jag för svår sudoku?\"],\"4apI84\":[\"Sudoku med stor stil att skriva ut\"],\"4gZ5Vw\":[\"Gratis och öppen källkod under licensen \",[\"SITE_LICENSE\"],\". Ingen reklam, inget konto, ingen spårning i spelet – läs <0>varför</0> eller bläddra i <1>hela källkoden på GitHub</1>. Apple och Apples logotyp är varumärken som tillhör Apple Inc., registrerade i USA och andra länder. App Store är ett servicemärke som tillhör Apple Inc. Google Play och Google Plays logotyp är varumärken som tillhör Google LLC.\"],\"52_TbA\":[\"Verifiera fiskar och wings på papper\"],\"57DMl6\":[\"Faller kedjorna på plats? <0>Häftet med sudoku att skriva ut på nivån Helvete</0> är den sista nivån, där varje sudoku kräver en tvingande kedja. Gå tillbaka till <1>sudoku att skriva ut på nivån Svår</1> för enbart fiskar och wings, eller spela Mardröm på skärmen på <2>sidan för sudoku på nivån Mardröm</2>.\"],\"5D6pgW\":[\"Ett lätt sudoku från samma generator som appen använder. Spela det direkt här.\"],\"5EmtkG\":[\"Är PDF:en med sudoku på nivån Helvete att skriva ut gratis?\"],\"5YPKNQ\":[\"Vem har bedömt de här sudokuna?\"],\"5a2b2H\":[\"Är de här sudokuna med 17 givna siffror?\"],\"5tWoLs\":[\"Lär dig sudoku\"],\"64gfbY\":[\"Spela sudoku för nybörjare nu\"],\"6JHmjr\":[\"Ja. Varje rutnät kontrolleras av en exakt täckningslösare med Dancing Links och en bitmasklösare innan det levereras, och vart och ett har exakt en lösning.\"],\"6Y2zqp\":[\"Är medelsvår sudoku svår?\"],\"6i2Miv\":[\"Mardröm har bara \",[\"clueCount\"],\" givna siffror, och det är häftet där den tryckta sidan verkligen gör nytta. Varje sudoku i det har testats mot en lösare som redan kan alla fiskar och wings – inklusive <0>swordfish</0> och <1>XY-Wing</1> – och behölls bara för att den lösaren stannade av. Det som avslutar dem är kedjeresonemang, och en kedja är mycket lättare att bygga på papper, där du kan skriva in länkarna med blyerts och följa dem, än på en trång skärm. Vårt urval på \",[\"sampleSize\"],\" sudokun mäter nivån till SE \",[\"seRatingRange\"],\".\"],\"6mE7Xy\":[\"En skärning eller ett par blir bara synligt när du kan se alla återstående kandidater i en rad, kolumn eller block på en gång, och därför hjälper papper här verkligen mer än en skärm: skriv små siffror i hörnet av varje tom ruta och skanna sedan en linje efter en siffra som är fångad i ett block, eller två rutor som delar exakt två kandidater. Inget av mönstren placerar en siffra på egen hand – de tar bara bort kandidater – så räkna med att markera några elimineringar innan en ny naken singel faktiskt dyker upp. Om du arbetar med blyerts i stället för penna kostar ett felaktigt märke ingenting att sudda ut.\"],\"6pYHox\":[\"<0>Nybörjare.</0> Går att lösa enbart med sista lediga rutan och nakna singlar.\"],\"6tfEbk\":[\"Varje sudoku kontrolleras av två oberoende lösningsalgoritmer för att säkerställa att det har exakt en lösning.\"],\"6yBCvI\":[\"Vad som gör ett sudoku till Mardröm\"],\"6z6usR\":[\"Vill du ha rekordsudokun på papper? Ladda ner <0>PDF:en med sudoku på Oändlighet att skriva ut</0>. Inte redo för dem än? Gå tillbaka till <1>Helvete-sudoku</1>, där varje sudoku kräver en tvingande kedja men ändå ligger inom räckhåll för vårt tekniksteg. Läs historierna bakom Everest och AI Escargot på sidan om de <2>svåraste sudokun</2>, jämför alla nivåer på sidan <3>Svårighetsnivåer för sudoku</3>, eller gå till <4>startsidan</4>.\"],\"6zwJ5l\":[\"Lätt ligger längst ner på SE-skalan (Sudoku Explainer) tillsammans med Nybörjare: vårt urval på \",[\"sampleSize\"],\" sudokun mäter SE \",[\"seRatingRange\"],\". De två nivåerna delar spann eftersom SE prissätter en dold singel till 1,5, under en naken singel på 2,3 – så tekniken som definierar Lätt är enligt den skalan billigare än den som definierar Nybörjare. Det som verkligen ändras är var du måste titta: en naken singel avläses från en ruta, en dold singel från en hel enhet. Det passar spelare som har klarat några sudokun för nybörjare och vill ha ett sudoku som märkbart tar längre tid att slutföra.\"],\"75Y3_I\":[\"Finns AI Escargot med i häftet att skriva ut?\"],\"7A3Fmz\":[\"Lättare nivå\"],\"7Y8jud\":[\"Spela svår sudoku nu\"],\"7Z44bB\":[\"Hittar du fiskar och wings tillförlitligt? Gå upp till <0>häftet med sudoku att skriva ut på nivån Mardröm</0> för kedjor och färgläggning. Backa till <1>medelsvårt sudoku att skriva ut</1> för enbart skärningar och delmängder, eller spela Svår på skärmen på <2>sidan för svår sudoku</2>.\"],\"7hktsm\":[\"Kom igång\"],\"7lhqPv\":[\"Kort sagt\"],\"7r6sCa\":[\"Textstorlek\"],\"7z1tpm\":[\"Nej. Anteckningsläget i en app håller reda på kandidaterna åt dig, uppdaterar dem automatiskt när du placerar siffror och låter dig ångra ett misstag utan att sudda.\"],\"83yMJR\":[\"Varje nivå från Nybörjare till Oändlighet har nu en egen guide som bryter ner exakt vad som skiljer en nivå från nästa – antal givna siffror, nödvändiga tekniker och en ärlig bedömning av hur svår varje nivå egentligen är. Börja på sidan <0>Svårighetsnivåer för sudoku</0>, eller se hur den står sig mot de <1>svåraste sudokun</1> som någonsin publicerats.\"],\"8GGOmr\":[\"Ett färdigt rutnät uppfyller alla tre samtidigt. Den överlappningen är det som gör sudoku lösbart med logik: en siffra som redan är utesluten av sin rad, sin kolumn och sitt block har ingenstans kvar att ta vägen, vilket ligger bakom nästan varje lösningsteknik. Varje namngiven teknik på den här webbplatsen, från den enklaste singeln till den längsta kedjan, är i grunden bara ett effektivare sätt att hålla reda på den överlappningen över många rutor på en gång i stället för en ruta i taget.\"],\"8HgdwA\":[[\"mediumClueCount\"],\" givna siffror, garanterat att stanna av på singlar och ge vika för skärningar och delmängder. Se <0>sidan för medelsvår sudoku</0> om du vill spela det digitalt.\"],\"8bwpsb\":[\"Gratis sudoku online innebär att spela det klassiska 9×9-sifferpusslet i webbläsare eller app utan köp, installationsgräns eller betalvägg, och \",[\"SITE_NAME\"],\" är en gratis implementation med öppen källkod av det – sju svårighetsnivåer från Nybörjare till Oändlighet, guider som förklarar teknikerna, ingen reklam och ingen spårning i spelet. Lös på webben eller installera appen, och behåll samma sviter och statistik överallt. Se <0>varför \",[\"SITE_NAME\"],\" är byggt på det här sättet</0> för hela, kontrollerbara resonemanget.\"],\"8hKEc0\":[\"Vanliga frågor om sudoku på nivån Mardröm\"],\"8j_b89\":[\"Mardröm slutar vid AIC – ett sudoku som står emot det ligger bortom vad de genererade nivåerna ger dig.\"],\"8ko6ZU\":[\"<0>Helvete</0> – garanterat att stanna av på AIC och kräva en tvingande kedja, hämtad från ett inbyggt, verifierat urval i stället för att genereras för en viss nivå.\"],\"8wCnRb\":[\"Sudokuna skrivs ut precis som de publicerades, utan omblandning, så att du kan jämföra ditt rutnät med originalen som tas upp på sidan om de <0>svåraste sudokun</0>. De skrivs ut med \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" per sida med plats för en hel uppsättning blyertsmarkeringar, vilket du kommer att behöva: på den här nivån håller de flesta lösare varje kandidat nedskriven och testar kedjor på ett separat blad. De sista sidorna innehåller de färdiga rutnäten, så du kan kontrollera en lång resonemangslinje utan att behöva avsluta den först.\"],\"92GEeo\":[\"Vill du värma upp först? <0>Häftet med sudoku på nivån Helvete att skriva ut</0> innehåller sudokun med tvingande kedjor som är svåra men ändå inom räckhåll för vårt tekniksteg. Föredrar du en skärm? Spela samma rekordsudokun på <1>sidan för sudoku på Oändlighet</1>, där varje spel blandar om rutnätet, eller bläddra bland alla häften på <2>sidan för sudoku att skriva ut</2>.\"],\"93EF2k\":[\"Hur många givna siffror har ett sudoku på nivån Helvete?\"],\"9AexDe\":[\"Ett sudoku som en lösare med enbart sista lediga rutan och nakna singlar kan avsluta förkastas som för lätt för nivån.\"],\"9COcEj\":[\"Fiskmönster: X-Wing, swordfish, jellyfish och deras finned- och sashimi-varianter. Wing-mönster: XY-Wing, XYZ-Wing och W-Wing.\"],\"9TF92W\":[\"Vårt urval på \",[\"sampleSize\"],\" lätta sudokun mäter SE \",[\"seRatingRange\"],\".\"],\"9e_cYH\":[\"Vanliga frågor om sudoku för nybörjare\"],\"9qTjdv\":[\"Hur många sudokun finns i PDF:en med medelsvårt sudoku att skriva ut?\"],\"9rfjS-\":[[\"PRINTABLE_LARGE_PRINT_PAGE_COUNT\"],\" sidor\"],\"AKA0Xn\":[\"Vilka tekniker kräver det här häftet med svår sudoku?\"],\"AV85q_\":[[\"clueCount\"],\" givna siffror av 81 rutor, löses från början till slut med sista lediga rutan, nakna singlar och dolda singlar.\"],\"AdsNQX\":[\"Ja. Vårt urval mäter Helvete till SE \",[\"hellSeRatingRange\"],\", och varje sudoku på Oändlighet har en publicerad bedömning mellan \",[\"lowestRatingLabel\"],\" och \",[\"highestRatingLabel\"],\". Sudokun på Helvete ger ändå vika för vårt tekniksteg; sudokun på Oändlighet gör det inte.\"],\"AfMtNM\":[\"Vanliga frågor om sudoku på Helvete\"],\"Ak9Eh5\":[\"Ett svårt sudoku från samma generator som appen använder. Spela det direkt här.\"],\"B-pBHn\":[\"Kedja av sudokunivåer\"],\"BJrGt8\":[\"Exakt en teknik. Varje sudoku för nybörjare går att avsluta med sista lediga rutan och nakna singlar; varje lätt sudoku går bevisligen inte det, och behöver minst en dold singel för att lösa upp låsningen.\"],\"BZz12Q\":[\"Skriv ut\"],\"C1_WBQ\":[\"Sudoku är ett logiskt pussel som spelas på ett 9×9-rutnät, indelat i nio 3×3-block. Målet är att fylla varje tom ruta med en siffra från 1 till 9 så att ingen siffra upprepas i någon rad, kolumn eller något block. Ett välformat sudoku börjar alltid med några rutor redan ifyllda – de givna siffrorna – och har alltid exakt en giltig lösning som går att nå enbart med logik, utan gissning.\"],\"C4kvBI\":[\"Vårt urval på \",[\"sampleSize\"],\" sudokun på Helvete mäter SE \",[\"seRatingRange\"],\", med <0/> som det vanligaste svåraste steget.\"],\"CA7v0X\":[\"Några av de här rutnäten börjar med så få som \",[\"HELL_CORPUS_MINIMUM_GIVEN_COUNT\"],\" givna siffror och ser nästan tomma ut vid första anblicken – de \",[\"PRINTABLE_BOOKLET_SIZE\"],\" sudokuna skrivs ut med \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" per sida med generös rutstorlek just för att det ska finnas plats att hålla reda på kandidater för hand längs en lång kedja. De sista sidorna innehåller de färdiga rutnäten, vilket är nästan nödvändigt på den här nivån: att verifiera en kedja av elimineringar med blotta ögat går långsamt, och en utskriven facit låter dig bekräfta slutläget utan att härleda hela vägen på nytt.\"],\"CAD1qm\":[\"En kedja följer en växlande följd av starka och svaga länkar, med start i en kandidat och utåt tills den bevisar en eliminering eller en placering, oavsett vilken gren som visar sig vara sann. X-Chain arbetar med en enda siffra; XY-Chain följer i stället en väg av bivalenta rutor. Enkel färgläggning ger ett nätverk av starka länkar för en siffra två växlande färger och tar bort varje kandidat som ser båda färgerna, och AIC generaliserar hela familjen genom att blanda siffror och ruttyper längs en sammanhängande kedja. Helvete börjar där allt detta tar slut. En tvingande kedja antar en kandidat, en rutas möjligheter eller ett områdes placeringar, följer varje konsekvens och behåller bara det som gäller i alla grenar – sidorna om <0>Nishio</0>, <1>cellkedjor</1> och <2>tvingande regionkedjor</2> går igenom ett exempel av varje. Ett sudoku kommer med i urvalet för Helvete bara om dess svåraste steg på den bedömningsoptimala vägen är en tvingande kedja, och bara om våra tekniksteg ändå kan avsluta det, så inget sudoku på Helvete kräver någonsin att du gissar.\"],\"CLPF0E\":[\"Bedömningarna är de värden som oberoende bedömare publicerar, inte våra egna mätningar.\"],\"ChsZzh\":[[\"hardClueCount\"],\" givna siffror, garanterat att stanna av på delmängder och ge vika för fisk- och wing-mönster. Se <0>sidan för svår sudoku</0> om du vill spela det digitalt.\"],\"DE2rA9\":[\"Givna siffror kontra svårighetsgrad\"],\"DE6q1A\":[\"Ja, per konstruktion. Mardröm slutar vid AIC, och inget sudoku på Helvete går att lösa med något som Mardröm tillåter. Vårt urval mäter Helvete till SE \",[\"hellSeRatingRange\"],\" och Mardröm till SE \",[\"nightmareSeRatingRange\"],\".\"],\"DFi0Zn\":[\"Svårare än allt annat i appen, med bred marginal. Vårt urval på \",[\"sampleSize\"],\" <0>Helvete</0>-sudokun mäter SE \",[\"hellSeRatingRange\"],\"; Oändlighet börjar på \",[\"lowestRatingLabel\"],\". Bedömningarna för Oändlighet är inte våra egna mätningar. Suuudokuuus bedömare prissätter SE-stegen bara så långt som till tvingande kedjor och nät och rapporterar \",[\"SE_RATING_CEILING\"],\" med en takflagga över det, så för de här sudokuna anger vi de siffror som oberoende bedömare publicerar, såsom <1>guiden om svårighetsbedömning</1> förklarar.\"],\"DIr2XR\":[\"Skärningar: pekande par, pekande trippel, block-rad-reduktion. Delmängder: naket par, dolt par.\"],\"DRVEbn\":[\"Vanliga frågor om sudoku på nivån Helvete att skriva ut\"],\"DRleO8\":[\"<0>Sista lediga rutan</0> – det enklaste draget som finns: att fylla i den sista tomma rutan i en enhet.\"],\"D_b_9m\":[\"Vanliga frågor om lätt sudoku\"],\"DgPHNt\":[\"En nästan-fisk: raderna eller kolumnerna ligger som en X-Wing eller <0>swordfish</0> bortsett från en eller två extra kandidater, finnen. Elimineringen gäller fortfarande, men bara i de rutor som både fisken och finnen ser.\"],\"DjGWF0\":[\"Skriv in varje återstående kandidat i de tomma rutor som är kvar och gå sedan igenom teknikindexet i svårighetsordning för att fortsätta rensa dem.\"],\"Drd4wO\":[\"En siffra som är begränsad till två rutor i ett block som också delar rad eller kolumn. Den kan då strykas från resten av den raden eller kolumnen, eftersom en av de två rutorna måste innehålla den.\"],\"DvhSrh\":[[\"clueCount\"],\" givna siffror av 81 rutor, garanterat med minst en dold singel men inget svårare.\"],\"E5Cz6q\":[[\"PRINTABLE_BOOKLET_SIZE\"],\" sudokun\"],\"ER15gL\":[\"Ett rekordsudoku från Oändlighet, ur samma kurerade urval som appen använder, omblandat. Spela det direkt här.\"],\"ETZyJl\":[\"Sju svårighetsnivåer från Nybörjare via Helvete till Oändlighet, där den översta nivån bjuder på rekordsudokun som Everest och AI Escargot\"],\"EYQUVy\":[\"<0>Svår.</0> Stannar alltid av på delmängder och ger alltid vika för en fisk eller ett wing-mönster.\"],\"EYVt4M\":[\"Största textstorlek\"],\"EyMkmB\":[\"Vilken är den lättaste svårighetsgraden i sudoku?\"],\"F_APxp\":[\"Gratis sudoku offline för iOS, Android och webben\"],\"FfmJIb\":[\"Är PDF:en med medelsvårt sudoku att skriva ut gratis?\"],\"Fgi0TQ\":[\"Inget i häftet kräver en fisk, en wing eller en kedja.\"],\"Fv02gG\":[\"Vårt publicerade urval på \",[\"sampleSize\"],\" svåra sudokun mäter nivån till SE \",[\"seRatingRange\"],\", med <0/> som det vanligaste svåraste steget – siffror som <1>guiden om sudokuns svårighetsbedömning</1> mäter direkt i stället för att anta. De \",[\"PRINTABLE_BOOKLET_SIZE\"],\" sudokuna här skrivs ut med \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" per sida med plats för att markera kandidater, och de lösta rutnäten på de avslutande sidorna låter dig bekräfta att en fiskeliminering verkligen höll.\"],\"G70CkD\":[\"Hur många givna siffror har ett medelsvårt sudoku?\"],\"GCBW83\":[\"Lös de billigaste placeringarna först: sista lediga rutan, sedan nakna singlar, sedan dolda singlar.\"],\"GOSVU9\":[\"Medelsvåra sudokun har \",[\"clueCount\"],\" givna siffror och garanterar att stanna av på singlar och ge vika för en skärning eller en delmängd.\"],\"GRoZ7D\":[\"Helvete-sudoku\"],\"GU9wm2\":[\"Kan jag använda dem i ett klassrum?\"],\"G_3WRn\":[\"Fungerar det offline?\"],\"GalvXV\":[\"Oändlighet är Suuudokuuus nivå bortom Helvete: ett kurerat urval av de svåraste sudokun som någonsin publicerats, de rekordrutnät som lösarvärlden fortfarande bråkar om, redo att spelas gratis. Varje sudoku på Oändlighet är ett känt sudoku med en publicerad Sudoku Explainer-bedömning (SE) på minst \",[\"minimumRatingLabel\"],\" – Arto Inkalas Everest, Platinum Blonde, AI Escargot, Golden Nugget och \",[\"additionalPuzzleCount\"],\" till – kontrollerat för en enda lösning innan det levereras. Det är de sudokun som vår guide om de <0>svåraste sudokun</0> beskriver; Oändlighet är där du spelar dem.\"],\"GeGHUl\":[\"Varje PDF är inställd på US Letter och ritad med vektorlinjer och text, så den skrivs ut skarpt i vilken storlek som helst. Öppna filen, skriv ut i 100 % skala (inte ”anpassa till sida”, som kan förvränga rutnätet på vissa skrivare) och skriv ut enkelsidigt om du vill ha lösningarna på separata blad från sudokuna.\"],\"Gfmra_\":[\"Ett lätt sudoku att börja med. Spela det direkt här, eller välj bland sju svårighetsgrader i appen.\"],\"Gu8Ueq\":[\"Vad som gör ett sudoku till Oändlighet\"],\"GzaiWG\":[\"Vanliga frågor om hur man spelar sudoku\"],\"H47ltZ\":[\"Hur skriver jag ut de här sudokuna?\"],\"HCMGUO\":[\"Måste man någonsin gissa?\"],\"HDn1fw\":[[\"clueCount\"],\" givna siffror av 81 rutor, garanterat med minst ett fisk- eller wing-mönster som går längre än alla delmängder.\"],\"HJEQpI\":[\"Allt från \",[\"HELL_CORPUS_MINIMUM_GIVEN_COUNT\"],\" till \",[\"HELL_CORPUS_MAXIMUM_GIVEN_COUNT\"],\". Helvete använder inte antalet givna siffror för att välja sina sudokun; ett sudoku kvalificerar sig genom att kräva en tvingande kedja, oavsett hur många siffror som är givna.\"],\"HPogd9\":[\"Varför rekommenderas papper för sudokun med kedjor?\"],\"HQCVxF\":[\"Är Nybörjare rätt nivå för ett barn eller någon som löser sudoku för första gången?\"],\"HSXkrR\":[\"Ett välformat sudoku har alltid exakt en lösning och kräver aldrig att man gissar.\"],\"HV3Yoi\":[\"Svår sudoku\"],\"Ht078b\":[\"Sudoku 1 från häftet Medel, ett av \",[\"PRINTABLE_BOOKLET_SIZE\"],\" i PDF:en.\"],\"I11j00\":[\"Mardröm är Suuudokuuus expertnivå – det som de flesta andra appar skulle kalla mycket svår eller expert. Ett sudoku på Mardröm har bara \",[\"clueCount\"],\" givna siffror av 81 rutor, och det är nivån där begränsade mönster inte längre räcker: varje sudoku här har kontrollerats mot en lösare som redan kan alla fiskar och alla wings upp till <0>W-Wing</0>, och får bara etiketten Mardröm för att den lösaren stannade av. Att avsluta ett sådant kräver kedjeresonemang – <1>X-Chain</1>, <2>XY-Chain</2>, <3>enkel färgläggning</3> och <4>AIC</4>, den växlande slutledningskedja som generaliserar de andra tre.\"],\"I3XIAf\":[\"Föredrar du en skärm? Spela Suuudokuuu nu\"],\"IANVSf\":[\"Nej. Det finns ingen reklam någonstans och ingen spårning i spelet; den här webbplatsen använder bara cookiefri, anonym sidstatistik.\"],\"IB9N-i\":[\"Vad är skillnaden mellan en given siffra och en kandidat?\"],\"IFKUNe\":[\"Inga blyertsmarkeringar, ingen elimineringslogik och ingen gissning krävs för något sudoku i häftet.\"],\"IOgWqm\":[\"Laddar brädet …\"],\"I_WAm2\":[\"Ja. När \",[\"SITE_NAME\"],\" väl är installerat genererar och löser det sudokun helt på din enhet, så det fungerar likadant utan uppkoppling.\"],\"IjDWTu\":[\"Så verifieras sudokuna\"],\"IlAsp5\":[\"Vilken svårighetsgrad i sudoku ska jag börja med?\"],\"IqBsZ0\":[\"Ja. PDF:en laddas ner gratis, utan konto och utan vattenstämpel, och innehåller ett fullständigt facit för varje sudoku.\"],\"IrAE3z\":[\"Lösare\"],\"Iu83qB\":[\"Sudoku 1 från häftet Nybörjare, ett av \",[\"PRINTABLE_BOOKLET_SIZE\"],\" i PDF:en.\"],\"JBdo3D\":[\"Vanliga frågor om svårighetsnivåer för sudoku\"],\"JJoC7U\":[\"Vad som gör ett sudoku svårt\"],\"Jrqsp5\":[\"Svårigheten här kommer från tekniken varje sudoku kräver, inte från antalet givna siffror.\"],\"JrrSQM\":[\"Vad är skillnaden mellan sudoku för nybörjare och lätt sudoku?\"],\"Jry7J2\":[\"Ett sudoku för nybörjare från samma generator som appen använder. Spela det direkt här.\"],\"KDXdKh\":[\"Ett sudoku på nivån Mardröm från samma generator som appen använder. Spela det direkt här.\"],\"KPuUq2\":[\"Skriv in kandidater när de enkla rutorna tar slut\"],\"KQe27c\":[\"Ingår lösningarna?\"],\"KVC9CP\":[\"Häftet med sudoku för nybörjare att skriva ut är en gratis PDF med sudokun med \",[\"clueCount\"],\" givna siffror där varje tom ruta går att nå med en sista ledig ruta eller en naken singel – en egenskap som varje sudoku kontrollerades för innan det kom med i PDF:en. Det är häftet att ge till någon som löser sudoku för första gången, ett klassrum som just lär sig reglerna, eller den som vill ha ett sudoku som aldrig kräver en andra gissning.\"],\"KiwVTj\":[\"Erbjuder Suuudokuuu en version av det här häftet med stor stil?\"],\"Kmcrz2\":[\"Ja. \",[\"SITE_NAME\"],\" är gratis och har öppen källkod, utan köp i appen, prenumerationer eller svårighetsnivåer bakom betalvägg.\"],\"L0XezG\":[\"Vad som gör ett sudoku till Helvete\"],\"L36iW5\":[\"Ja. Suuudokuuus kod, inklusive generatorn bakom de här sudokuna, har öppen källkod under MIT-licensen, och den här webbplatsen sätter ingen begränsning för att skriva ut eller dela vidare PDF:erna – även att dela ut dem i ett klassrum, en lektion eller ett paket med arbetsblad.\"],\"L3TeBG\":[\"Hur svårt är sudoku för nybörjare?\"],\"LBVuWJ\":[\"Sudoku för nybörjare\"],\"LDOq68\":[\"Hur många sudokun finns i PDF:en med sudoku på nivån Mardröm att skriva ut?\"],\"LI4SwS\":[\"Vad som gör ett sudoku medelsvårt\"],\"LNoRL7\":[\"<0>Lätt.</0> Lägger till dolda singlar, fortfarande utan att du behöver hålla koll på kandidater.\"],\"LfQJwZ\":[\"En försättssida anger i förväg antalet sudokun och sidor, och därefter skrivs \",[\"PRINTABLE_BOOKLET_SIZE\"],\" sudokun ut med \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" per sida, så ett enda blad rymmer \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" kompletta rutnät. De sista sidorna innehåller varje löst rutnät i samma upplägg, så att kontrollen av ett svar aldrig innebär att leta på en sida med ett annat format. Hela filen består av vektorgrafik och ett standardtypsnitt för PDF, så den skrivs ut skarpt i vilken storlek skrivaren klarar. Vårt publicerade urval på \",[\"sampleSize\"],\" lätta sudokun mäter SE \",[\"seRatingRange\"],\" – siffror som <0>guiden om sudokuns svårighetsbedömning</0> mäter direkt i stället för att anta.\"],\"LrHydF\":[\"Läs <0>guiden för hur man spelar</0> för de tre reglerna och en genomgång av dina första drag, eller slå upp valfri term i <1>sudokuordlistan</1>, som definierar varje teknik och varje begrepp som guiderna använder.\"],\"Lxq-zS\":[\"Sudoku med stor stil\"],\"M1Yfw6\":[\"Minst en <0>dold singel</0> per sudoku, ovanpå sista lediga rutan och de nakna singlar som Nybörjare redan använder, och inget svårare.\"],\"MLFx1h\":[\"Ja. Lätt är källnivån för PDF:en med stor stil, med ett urval på \",[\"PRINTABLE_LARGE_PRINT_SIZE\"],\" sudokun med större rutor för läsare som vill ha mer utrymme att skriva.\"],\"MREaAq\":[\"Allt som Medel kräver, plus minst ett fisk- eller wing-mönster: X-Wing, swordfish, jellyfish, deras finned- och sashimi-varianter, XY-Wing, XYZ-Wing eller W-Wing. Ett av dem krävs alltid, eftersom ett sudoku som inte behöver något sådant får betyget Medel i stället.\"],\"MVYMfh\":[\"Svårighetsgrader för sudoku\"],\"M_zq3f\":[\"Vanliga frågor om sudoku på Oändlighet att skriva ut\"],\"Mz7rRO\":[\"Kontrollera varje rad, kolumn och block efter ett som redan har åtta av nio rutor ifyllda, och placera den saknade siffran i den tomma rutan.\"],\"N0hmpU\":[[\"clueCount\"],\" givna siffror av 81 rutor – bara en färre än Medel, och just därför definieras nivån av vilka tekniker den kräver snarare än av antalet givna siffror.\"],\"NQTfla\":[\"Vanliga frågor om sudoku för nybörjare att skriva ut\"],\"NeWjyh\":[\"<0>Nybörjare</0> – \",[\"newbieClueCount\"],\" givna siffror, löses enbart med sista lediga rutan och nakna singlar.\"],\"NkdmkS\":[\"Vilka tekniker kräver det här häftet med sudoku på nivån Mardröm?\"],\"Nq65SI\":[\"Nej. Antalet givna siffror och svårighetsgraden är två skilda saker – se <0>guiden om sudokun med 17 givna siffror</0>. De här sudokuna är svåra för att vart och ett kräver en tvingande kedja, inte för hur många siffror de börjar med.\"],\"NuoZju\":[\"Klarat ett sudoku på Helvete och vill ha mer? <0>Sudoku på Oändlighet</0> bjuder på rekordsudokun – Everest, Platinum Blonde, AI Escargot – som ligger bortom även våra tvingande kedjor. Inte redo för kedjor än? Gå tillbaka till <1>Mardröm-sudoku</1>, som kräver samma resonemang med mer av rutnätet redan ifyllt. Föredrar du papper? Ladda ner <2>PDF:en med sudoku att skriva ut på nivån Helvete</2>. Bläddra bland <3>teknikindexet</3>, särskilt X-Chain, XY-Chain, enkel färgläggning och AIC, <4>guiden för hur man spelar</4>, <5>guiden om sudokun med 17 givna siffror</5>, alla nivåer på sidan <6>Svårighetsnivåer för sudoku</6>, eller gå till <7>startsidan</7>.\"],\"Nyd-0x\":[\"Hur många givna siffror har ett svårt sudoku?\"],\"NzFVBG\":[\"Varför är en fisk eller en wing lättare att verifiera på papper?\"],\"OMs2n2\":[\"Redo att kedja ihop elimineringar i stället för att upptäcka former? Gå upp till <0>Mardröm-sudoku</0>, eller backa till <1>medelsvår sudoku</1> för ett sudoku med skärningar och delmängder. Föredrar du papper? Ladda ner <2>PDF:en med svårt sudoku att skriva ut</2>. Se <3>teknikindexet</3>, <4>guiden för hur man spelar</4>, alla nivåer på sidan <5>Svårighetsnivåer för sudoku</5>, eller gå till <6>startsidan</6>.\"],\"OubwsB\":[\"Hur många sudokun finns i PDF:en med sudoku för nybörjare att skriva ut?\"],\"P2bU2d\":[\"Vad som gör ett sudoku lätt\"],\"P6JVwt\":[\"Sällan. De flesta spelare kan hålla de få kandidater som en dold singel kräver i huvudet, men det skadar aldrig att skriva ner dem på en mer fullpackad rad.\"],\"PDbaU0\":[\"Behöver jag blyertsmarkeringar i sudokun för nybörjare?\"],\"PFKt-9\":[\"Svår går ner till \",[\"clueCount\"],\" givna siffror, och det här är det första häftet med sudoku att skriva ut på webbplatsen där enbart delmängder inte tar dig hela vägen. Varje sudoku i det har testats mot en lösare som redan kan alla skärningar och alla delmängder, och behölls bara för att den lösaren stannade av. Det som avslutar dem är en fisk eller en wing: <0>X-Wing</0> och dess större och finned-släktingar, eller något av de bivalenta wing-mönstren.\"],\"PGxh1d\":[\"Vad är en finned fisk i sudoku?\"],\"PKS4Or\":[\"Är PDF:en med sudoku på Oändlighet att skriva ut gratis?\"],\"PYziuK\":[\"En kedja har ingen fast form och byggs länk för länk, vilket är mycket lättare att hålla reda på om du skriver ner varje stark och svag länk än om du scrollar på en liten skärm.\"],\"PZQD8F\":[\"Spela nu\"],\"Pbm-BS\":[\"Hur garanterar Suuudokuuu en nivås teknikkrav?\"],\"Pg0uLs\":[\"Alla nivåer är gratis att spela, utan reklam och utan registrering. <0>Spela ett sudoku nu</0> på någon av de sju nivåerna, eller läs hela genomgången av givna siffror och nödvändiga tekniker på sidan <1>Svårighetsnivåer för sudoku</1>. Lär du dig på papper? Börja med <2>PDF:en med sudoku att skriva ut för nybörjare</2>.\"],\"PgRaz8\":[\"Spela lätt sudoku nu\"],\"PivQ2i\":[\"Mycket. Varje sudoku i uppsättningen Oändlighet har en publicerad SE-bedömning på minst \",[\"lowestRatingLabel\"],\", långt över allt som de genererade nivåerna eller urvalet för Helvete ger. Vår egen bedömare slutar prissätta SE-stegen vid \",[\"SE_RATING_CEILING\"],\", så siffrorna som anges här kommer från oberoende bedömare, och vår teknikmotor klarar inte av att avsluta något av de här rutnäten på egen hand. Räkna med att behöva långa tvingande kedjor och tvingande nät, och räkna med att ett enda sudoku tar mycket längre tid än allt annat på den här webbplatsen.\"],\"Pqhtap\":[\"Lätt\"],\"PrxlWP\":[\"Vanliga frågor om lätt sudoku att skriva ut\"],\"PszyWW\":[\"Vad är det snabbaste sättet att bli bättre på sudoku?\"],\"PzS0uu\":[\"Svåra sudokun har \",[\"clueCount\"],\" givna siffror och garanterar minst ett fisk- eller wing-mönster som går längre än alla delmängder.\"],\"Q5B0cW\":[\"Helvete\"],\"QBE_L9\":[\"<0>Mardröm.</0> Stannar alltid av på fiskar och wings och ger alltid vika för kedje- eller färgläggningslogik.\"],\"Qo4hE6\":[\"En kedja följer en växlande följd av starka och svaga länkar mellan kandidater. Den börjar i ena änden och resonerar utåt tills de två ändarna bevisar en eliminering, oavsett vilken av dem som visar sig vara sann. X-Chain gör detta med en enda siffra; XY-Chain följer i stället en väg av bivalenta rutor och byter siffra i varje steg. Enkel färgläggning ger ett nätverk av starka länkar för en siffra två växlande färger och tar bort varje kandidat som ser båda färgerna. AIC samlar allt detta i en teknik där siffror och länktyper blandas längs en enda sammanhängande kedja. Skillnaden mot en fisk eller en wing handlar inte om finess utan om form: en wing är ett fast mönster av tre eller fyra rutor som man lär sig känna igen, medan en kedja saknar fast storlek och måste byggas steg för steg. Mardröm slutar vid AIC – allt som fortfarande står emot ligger bortom vad de genererade nivåerna ger dig.\"],\"R1g33v\":[\"Inget sudoku, bara rutnätet: ett 9×9-rutnät i helsidesformat för att skriva av ett sudoku från en bok eller tidning, plus en andra sida med fyra mindre rutnät för snabba övningsblad. Praktiskt för lärare som gör egna arbetsblad eller för alla som skriver av ett sudoku de hittat någonstans utan en utskriftsvänlig version.\"],\"RJUjbN\":[\"Tips för att lösa med blyertsmarkeringar\"],\"RMq7iB\":[\"En fisk tittar på en siffra över flera linjer samtidigt. X-Wing är den minsta: en siffra som är begränsad till samma två kolumner i två rader kan strykas från resten av de kolumnerna, för vilken av raderna som än får siffran är kolumnerna redan bestämda. En <0>swordfish</0> sträcker ut samma idé över tre linjer och en jellyfish över fyra. Finned- och sashimi-varianterna mjukar upp grundmönstret genom att tillåta en extra kandidat som ändå ger en mindre, säker eliminering när man tar hänsyn till den – och i vårt urval inträffar de betydligt oftare än de klassiska formerna. Wings fungerar på ett annat sätt: en XY-Wing länkar ihop tre bivalenta rutor så att en kandidat som delas av två av dem kan strykas överallt där båda ser, XYZ-Wing ger även pivotrutan den kandidaten, och W-Wing förbinder två likadana bivalenta rutor genom en stark länk på en gemensam siffra. Svår slutar vid W-Wing: ett sudoku som fortfarande inte rör sig efter att alla fiskar och wings har prövats är ett sudoku på nivån Mardröm, inte Svår.\"],\"RRGDQM\":[\"Nybörjare är den lättaste av Suuudokuuus sju nivåer, följd av Lätt, Medel, Svår, Mardröm, Helvete och Oändlighet i stigande svårighetsordning.\"],\"Rj2Y_n\":[\"De mest kända Infinity-rutnäten har egna sidor, var och en spelbar, utskrivbar och löst steg för steg av motorn: <0>AI Escargot</0>, <1>Golden Nugget</1>, <2>Platinum Blonde</2>, <3>Everest</3>, <4>Kolk</4> och <5>Silver Plate</5>.\"],\"Rwv4vE\":[\"En tvingande kedja, på varje sudoku, ovanpå de kedjor, den färgläggning, de fiskar, wings och delmängder som de tidigare nivåerna redan kräver. X-Chain, XY-Chain, enkel färgläggning och AIC tar dig långt, men aldrig hela vägen fram. En <0>tvingande Nishio-kedja</0> är det vanliga sättet att lösa upp låsningen.\"],\"SPFeoH\":[\"Vanliga frågor om svårt sudoku att skriva ut\"],\"ScJ9fj\":[\"Integritetspolicy\"],\"Sg-BY5\":[\"Antalet givna siffror är inte svårighetsgraden. Det är bara indata: färre siffror från start betyder färre omedelbara placeringar, vilket tvingar lösaren – människa eller maskin – att ta till fler namngivna tekniker innan rutnätet rör sig igen. Suuudokuuu plockar bort siffror ur ett löst rutnät ner till ett mål per nivå, kontrollerar att resultatet fortfarande har exakt en lösning och gör sedan det som faktiskt definierar nivån: det löser sudokut två gånger, en gång med tekniksteget från nivån under och en gång med sitt eget, och behåller bara sudokut om den första lösningen misslyckas och den andra lyckas. Sudokun som missar kasseras och ett nytt genereras. Därför anges varje nivå ovan som en garanti och inte som en förhoppning. Det <0>fullständiga teknikindexet</0> listar varje mönster som stegen innehåller, i den ordning en lösare prövar dem. Inom ett band kan två sudokun ändå skilja sig mycket åt – <1>givna siffror kontra svårighetsgrad</1> mäter exakt hur mycket.\"],\"Sjq7vw\":[\"Stryk för varje återstående tom ruta alla siffror som redan används i dess rad, kolumn och block. Om exakt en siffra återstår, placera den.\"],\"T-6Uzi\":[\"Arto Inkalas Everest (2010), 21 givna siffror, publicerat med SE 11.9.\"],\"T5khAF\":[\"Spela sudoku på nivån Helvete nu\"],\"T91vKp\":[\"Spela\"],\"TW-b-m\":[\"Nej. Antalet givna siffror är bara indata som tvingar en lösare mot en bredare uppsättning tekniker; det är det teknikband som generatorn verifierar som faktiskt definierar varje nivå. <0>Guiden om givna siffror kontra svårighetsgrad</0> mäter skillnaden direkt.\"],\"T_JQXy\":[\"Vårt urval på \",[\"sampleSize\"],\" medelsvåra sudokun mäter SE \",[\"seRatingRange\"],\".\"],\"T_R-Qz\":[\"Primär\"],\"TiHBaL\":[\"Svår sudoku är en svårighetsnivå som börjar på \",[\"clueCount\"],\" givna siffror av 81 rutor och definieras av vad en lösare med enbart delmängder inte kan avsluta: varje sudoku på nivån har körts genom en lösare utrustad med alla skärningar och alla delmängder upp till den <0>dolda kvadruppeln</0>, och behölls bara för att den lösaren kört fast. Det som bryter låsningen är en fisk – <1>X-Wing</1>, <2>swordfish</2>, <3>jellyfish</3> och deras <4>finned</4>- och <5>sashimi</5>-varianter – eller en wing: <6>XY-Wing</6>, <7>XYZ-Wing</7> och <8>W-Wing</8>.\"],\"TqC0fH\":[[\"clueCount\"],\" givna siffror av 81 rutor, och varje tom ruta går att lösa med sista lediga rutan eller naken singel.\"],\"U1U2tC\":[\"Hur många givna siffror har ett lätt sudoku?\"],\"U2AKxD\":[\"Vanliga frågor om sudoku att skriva ut\"],\"U9wBFD\":[\"Lätt håller sig inom logik med enbart singlar och är därför fortfarande nybörjarvänligt. Den enda färdighet som tillkommer jämfört med Nybörjare är att upptäcka en siffra som inte passar någon annanstans i en enhet.\"],\"UF5_iX\":[\"Standardtextstorlek\"],\"UILsns\":[\"Skriv in kandidater i en ruta först när skanningen inte längre ger några placeringar.\"],\"Umo747\":[\"Inga blyertsmarkeringar, ingen elimineringslogik och ingen gissning krävs någonsin.\"],\"Uq9L94\":[[\"clueCount\"],\" givna siffror av 81 rutor, klart under en tredjedel av rutnätet.\"],\"UveQZj\":[\"Vårt urval på \",[\"sampleSize\"],\" sudokun på Mardröm mäter SE (Sudoku Explainer) \",[\"seRatingRange\"],\", med <0/> som det vanligaste svåraste steget. AIC är taket här: varje sudoku på Mardröm faller för det, och <1>nivån Helvete</1> börjar exakt där det slutar, med sudokun som kräver en tvingande kedja. Några av de sudokuna på Helvete har fler givna siffror än Mardröm, vilket är det tydligaste beviset på webbplatsen för att antalet givna siffror och svårighetsgraden är skilda saker. De uppmätta tabellerna finns i vår <2>guide om sudokuns svårighetsbedömning</2>. Kvalitativt är det här den punkt där svårigheten slutar handla om snabbhet och i stället handlar om att hålla en hel slutledningskedja i huvudet utan att tappa tråden.\"],\"V9j1Oq\":[\"Nej. Varje sudoku på nivån verifieras som lösbart med tekniksteget upp till AIC innan det levereras, så en fullständig kedja finns alltid – att hitta den är jobbet.\"],\"VHv3Qz\":[\"Sudokun på Oändlighet har \",[\"INFINITY_MINIMUM_GIVEN_COUNT\"],\" till \",[\"INFINITY_MAXIMUM_GIVEN_COUNT\"],\" givna siffror och kontrolleras av två oberoende lösningsalgoritmer för att säkerställa en enda lösning.\"],\"VT7jaN\":[\"Ett sudoku på nivån Helvete från samma verifierade urval som appen använder. Spela det direkt här.\"],\"VUJcE0\":[\"Ja. Varje sudoku i häftet går att lösa enbart med en sista ledig ruta eller en naken singel, så ingen kandidatmarkering eller elimineringslogik krävs någonsin.\"],\"Vmq46x\":[\"När sista lediga rutan och nakna singlar känns automatiska, gå vidare till <0>häftet med lätt sudoku att skriva ut</0>, som lägger till exakt en teknik ovanpå: den dolda singeln. Vill du hellre spela sudokun för nybörjare på en skärm, besök <1>sidan för sudoku för nybörjare</1>. För hela tekniksteget och de uppmätta data som ligger bakom påståendena, se <2>teknikindexet</2> och <3>guiden om sudokuns svårighetsbedömning</3>.\"],\"W1nEnp\":[[\"clueCount\"],\" givna siffror av 81 rutor, en tredjedel av rutnätet är ifyllt redan från start.\"],\"W8o5ac\":[\"De andra nivåerna definieras av de tekniker de kräver. Oändlighet definieras av rykte, uppmätt: ett sudoku kvalificerar sig bara om oberoende bedömare har publicerat en SE-bedömning på \",[\"minimumRatingLabel\"],\" eller högre för det. De flesta av de \",[\"infinityCorpusSize\"],\" kommer från en ögonblicksbild från 2011 av databasen över svåraste sudokun som lösarvärlden underhåller; resten är de namngivna klassikerna, hämtade från de forumtrådar och publikationer där de först dök upp. Innan urvalet packas in i appen bekräftar både en exakt täckningslösare med Dancing Links och en bitmasklösare att varje rutnät har exakt en lösning.\"],\"W9xBMf\":[\"Nya lösare bör börja på Nybörjare och gå upp en nivå i taget; varje steg lägger till exakt en ny teknik jämfört med nivån före, ända upp till Svår. Se först <0>guiden för hur man spelar</0> om de tre grundreglerna fortfarande är obekanta.\"],\"WB-pGD\":[\"Det här häftet skriver ut \",[\"PRINTABLE_BOOKLET_SIZE\"],\" av de svåraste sudokun som någonsin publicerats, hämtade från Suuudokuuus nivå Oändlighet: Arto Inkalas Everest, AI Escargot, Platinum Blonde, Golden Nugget och andra rekordrutnät, vart och ett med en publicerad SE-bedömning (Sudoku Explainer) mellan \",[\"lowestRatingLabel\"],\" och \",[\"highestRatingLabel\"],\". Varje sudoku har exakt en lösning, och de lösta rutnäten finns längst bak.\"],\"WG8Ftb\":[\"Hur många givna siffror har ett sudoku för nybörjare?\"],\"WTwN7-\":[\"Spela \",[\"SITE_NAME\"]],\"WmW-Gm\":[\"Utskriftsutrymmet betyder mer här än på de lättare nivåerna, eftersom skärningar och par bygger på att markera kandidater i marginalerna. De \",[\"PRINTABLE_BOOKLET_SIZE\"],\" sudokuna skrivs ut med \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" per sida i full rutstorlek, vilket lämnar tillräckligt med plats runt varje siffra för att skriva in de små siffror som en skärning eller ett par resonerar över. Lösta rutnät avslutar filen så att du kan kontrollera dina kandidatmarkeringar mot ett bekräftat svar. Vårt publicerade urval på \",[\"sampleSize\"],\" medelsvåra sudokun mäter SE \",[\"seRatingRange\"],\" – siffror som <0>guiden om sudokuns svårighetsbedömning</0> mäter direkt i stället för att anta.\"],\"WrhTzj\":[\"Ja. Varje svårighetshäfte och uppsättningen med stor stil har de fullständiga lösta rutnäten på de sista sidorna, framtagna av samma lösare som verifierar att varje sudoku har exakt en lösning innan det levereras.\"],\"WwMVff\":[\"Hur svårt är sudoku på nivån Mardröm?\"],\"XGVJW3\":[\"Sudokuordlista\"],\"XORYRH\":[\"De \",[\"PRINTABLE_BOOKLET_SIZE\"],\" sudokuna skrivs ut med \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" per sida, i en storlek som gör att en kedja som korsar hela rutnätet fortfarande ryms bekvämt på ett blad. Lösta rutnät avslutar häftet, vilket betyder mer här än på de lättare nivåerna – en enda missad eliminering mitt i en kedja växer snabbt, och ett utskrivet facit fångar upp den. Den uppmätta spridningen bakom de här påståendena finns i <0>guiden om sudokuns svårighetsbedömning</0>.\"],\"XpU6Tm\":[\"Varför använder Helvete ett fast urval av sudokun i stället för att generera dem?\"],\"XzG50N\":[\"Helvete är Suuudokuuus svåraste teknikgraderade nivå – det som de flesta konkurrenter kallar evil eller extrem. Ett sudoku på Helvete definieras av det resonemang det kräver, inte av hur få siffror det börjar med: inget sudoku på Helvete går att avsluta med någon teknik som Mardröm tillåter, så varje sådant kräver en tvingande kedja. Till skillnad från de genererade nivåerna hämtas Helvete från ett inbyggt urval av publicerade svåra sudokun, verifierade av två oberoende lösare innan de levereras, och varje sudoku går ändå att lösa med våra tekniksteg utan att gissa. Räkna med att först använda varje kedje- och färgläggningsmönster – <0>X-Chain</0>, <1>XY-Chain</1>, <2>enkel färgläggning</2> och <3>AIC</3> – innan en tvingande kedja bryter låsningen.\"],\"Y3fLpk\":[\"Hur många sudokun finns i PDF:en med svårt sudoku att skriva ut?\"],\"YGCzAJ\":[\"Varje sudokukandidat löses två gånger: en gång med teknikstegen från nivån under, som måste misslyckas, och en gång med sitt eget, som måste lyckas. Sudokun som missar något av proven kasseras och genereras om.\"],\"YM-Le2\":[[\"clueCount\"],\" givna siffror av 81 rutor, garanterat med minst en kedje- eller färgläggningsteknik som går längre än alla fiskar och wings.\"],\"Y_LLdr\":[\"Är PDF:en med lätt sudoku att skriva ut gratis?\"],\"Yj1j4Z\":[\"Sudoku 1 från häftet Helvete, ett av \",[\"PRINTABLE_BOOKLET_SIZE\"],\" i PDF:en.\"],\"YjxNca\":[\"Spela sudoku på Oändlighet nu\"],\"Z-7bqV\":[\"Vanliga frågor om svår sudoku\"],\"Z9Mfy1\":[\"Vad häftet innehåller\"],\"Z9MhMF\":[\"Vad som gör ett sudoku till Nybörjare\"],\"ZBT6Lr\":[[\"infinityCorpusSize\"],\" rekordsudokun med \",[\"INFINITY_MINIMUM_GIVEN_COUNT\"],\" till \",[\"INFINITY_MAXIMUM_GIVEN_COUNT\"],\" givna siffror, publicerade med SE \",[\"lowestRatingLabel\"],\" till \",[\"highestRatingLabel\"],\".\"],\"ZPXer3\":[\"Anteckningar och kandidater\"],\"Zm7CE_\":[\"Varje teknik som \",[\"SITE_NAME\"],\" använder för att ta fram ledtrådar är dokumenterad med ett genomarbetat exempel hämtat direkt från lösningsmotorn. Börja med det <0>fullständiga teknikindexet</0>, eller hoppa rakt in i något av de första mönster som de flesta spelare lär sig.\"],\"ZtZST0\":[\"Varje sudoku kräver en tvingande kedja, hämtad från vårt inbyggda, verifierade urval för Helvete. Se <0>sidan för sudoku på nivån Helvete</0> om du vill spela det digitalt.\"],\"_4AR-Z\":[[\"PRINTABLE_BOOKLET_PAGE_COUNT\"],\" sidor\"],\"_YA7YX\":[\"Ja, tillsammans med Everest, Platinum Blonde och Golden Nugget. Häftet skriver ut sudokuna precis som de ursprungligen publicerades.\"],\"_kK7k_\":[\"Vad är skillnaden mellan en wing och en kedja?\"],\"_nkVQD\":[\"Inget i häftet kräver en kedja – det börjar först på nivån Mardröm.\"],\"_t9fa1\":[\"Vad är sudoku på Oändlighet?\"],\"a3pVqb\":[\"Vanliga frågor\"],\"aF08Xt\":[\"Sju. Nybörjare, Lätt, Medel, Svår, Mardröm och Helvete utgör tekniksteget, var och en definierad av ett antal givna siffror och ett garanterat teknikband snarare än en marknadsföringsetikett. Oändlighet ligger ovanför dem, ett kurerat urval av rekordsudokun valda efter publicerad bedömning.\"],\"aIDRsS\":[\"<0>Medel.</0> Stannar alltid av på singlar och ger alltid vika för skärningar och delmängder – pekande par, block-rad-reduktion, nakna och dolda par upp till kvadrupplar.\"],\"aMv0h8\":[\"Ett medelsvårt sudoku från samma generator som appen använder. Spela det direkt här.\"],\"aOHWJD\":[\"<0>Naken singel</0> – en ruta som bara har exakt en kandidat kvar.\"],\"aQ3vvP\":[[\"nightmareClueCount\"],\" givna siffror, garanterat att stanna av på wings och ge vika för kedjor och färgläggning. Se <0>sidan för sudoku på nivån Mardröm</0> om du vill spela det digitalt.\"],\"aeZiiA\":[\"Varje sudoku garanteras ha exakt en lösning, utan att man behöver gissa\"],\"agPptk\":[\"Medel\"],\"ajKnoT\":[\"Sudokuns tre regler\"],\"alOHPr\":[\"Redo för att skärningar och delmängder ska börja spela roll? Gå vidare till <0>häftet med medelsvårt sudoku att skriva ut</0>, eller backa till <1>sudoku för nybörjare att skriva ut</1> för ett ännu mildare rutnät. Vill du hellre spela lätta sudokun på en skärm, besök <2>sidan för lätt sudoku</2>.\"],\"bIMckF\":[\"Standard-PDF:en använder redan ett generöst upplägg med \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" sudokun per sida. För större rutor specifikt, se <0>häftet med lätt sudoku att skriva ut</0>, som också är källnivån för vår PDF med stor stil.\"],\"bJo3n2\":[\"Sudokutips\"],\"bLowF0\":[\"Lös dina första rutor\"],\"bMqX8c\":[\"Leta efter enheter med saknade siffror\"],\"bQP2nt\":[\"Löser du lätta sudokun utan att ta till en dold singel? Gå tillbaka till <0>sudoku för nybörjare</0>, eller upp till <1>medelsvår sudoku</1>, där skärningar och dina första par dyker upp. Föredrar du papper? Ladda ner <2>häftet med lätt sudoku att skriva ut</2>, eller se guiden <3>sudoku för seniorer</3> för alternativ med stor stil och bättre komfort. Se hela <4>teknikindexet</4>, guiden <5>för hur man spelar</5>, eller alla nivåer på sidan <6>Svårighetsnivåer för sudoku</6> tillbaka på <7>startsidan</7>.\"],\"bUGU7d\":[\"Storlek och form. En wing är ett fast mönster av tre eller fyra rutor som du lär dig känna igen med en blick; en kedja byggs länk för länk och kan vara hur lång som helst, vilket är därför kedjor ligger ett helt band över wings på SE-skalan.\"],\"bVG9Tb\":[\"Att skriva ut\"],\"bY8tm0\":[\"Källkod på GitHub\"],\"bc8DGE\":[\"Fyll varje tom ruta med en siffra från 1 till 9 så att ingen siffra upprepas i en rad, en kolumn eller ett 3×3-block.\"],\"c38U12\":[\"Vad är ett pekande par?\"],\"c3R2ID\":[\"Sista lediga rutan och naken singel är de två första strategier som Suuudokuuus lösningsmotor prövar på varje sudoku på alla svårighetsnivåer, eftersom de är de billigaste slutsatserna att verifiera. Det som skiljer Nybörjare åt är att nivån definieras som de sudokun som aldrig behöver något annat. Plockar man bort fler siffror stannar en lösare till slut av utan dolda singlar, skärningar eller delmängder, och generatorn kastar tillbaka de sudokuna i stället för att märka dem som Nybörjare. Om du kan läsa en rad och peka ut den enda siffra som saknas har du redan varje färdighet som ett sudoku för nybörjare kräver.\"],\"cK6miM\":[\"Svårighetsgrad\"],\"cVxfVr\":[\"Nej. Båda teknikerna som ett sudoku för nybörjare kräver kan avläsas direkt på brädet, vilket är precis varför de är de snabbaste slutsatserna i spelet.\"],\"d4hJrp\":[\"Svårare nivå\"],\"d5hiJp\":[\"Därför stannar spelarna\"],\"dKAb7E\":[\"Varje sudoku på Helvete kräver en tvingande kedja: inget går att lösa med de tekniker som Mardröm tillåter, upp till AIC.\"],\"dXoieq\":[\"Sammanfattning\"],\"do-_4n\":[\"Minst en fisk (<0>X-Wing</0> och dess större och finned-släktingar) eller ett bivalent wing-mönster, ovanpå varje skärning och delmängd som de lättare häftena redan kräver.\"],\"dvRtE-\":[\"Sju: Nybörjare, Lätt, Medel, Svår, Mardröm, Helvete och Oändlighet. Sudokun på Helvete kommer från ett inbyggt, verifierat urval av sudokun som alla kräver en tvingande kedja, bortom allt som Mardröm begär, och <0>Oändlighet</0> bjuder på rekordsudokun som Everest och AI Escargot.\"],\"dyGlGe\":[\"Uppsättningen med stor stil använder samma logik som nivån Lätt i häftet ovan, men med \",[\"PRINTABLE_LARGE_PRINT_PUZZLES_PER_PAGE\"],\" sudokun per sida i stället för \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\", så varje ruta och siffra skrivs ut märkbart större. Den passar personer med nedsatt syn, klassrumsutdelningar som läses på avstånd och alla som tycker att standardrutnätet känns trångt på papper. Se <0>sidan om sudoku med stor stil</0> för utskriftstips och alternativet på skärmen, eller guiden <1>sudoku för seniorer</1> för hela genomgången med fokus på komfort.\"],\"e0NrBM\":[\"Projekt\"],\"eBV_Xh\":[\"Sudokun på Mardröm har \",[\"clueCount\"],\" givna siffror och garanterar minst en kedje- eller färgläggningsteknik som går längre än alla fiskar och wings.\"],\"eJ9n-i\":[\"Ny på själva rutnätet? Börja med <0>guiden för hur man spelar</0> för de tre reglerna och dina första placeringar innan du väljer nivå ovan.\"],\"eJum-4\":[[\"PRINTABLE_BOOKLET_SIZE\"],\" sudokun fördelade på \",[\"PRINTABLE_BOOKLET_PAGE_COUNT\"],\" sidor, utskrivna \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" per sida med de lösta rutnäten längst bak.\"],\"emFA81\":[\"Vanliga frågor om sudoku på nivån Mardröm att skriva ut\"],\"enA4B7\":[\"Är svår sudoku svårare än Mardröm?\"],\"eo2JDj\":[\"Har du kört fast i ett sudoku?\"],\"eozBux\":[\"Inte nödvändigtvis. Sudokun på Helvete har \",[\"HELL_CORPUS_MINIMUM_GIVEN_COUNT\"],\" till \",[\"HELL_CORPUS_MAXIMUM_GIVEN_COUNT\"],\" givna siffror, hämtade från ett inbyggt urval som kontrollerats av två oberoende lösningsalgoritmer och filtrerats till sudokun som kräver en tvingande kedja, i stället för att genereras på nytt när de skrivs ut.\"],\"ev-7sc\":[\"Nej. Svår slutar vid W-Wing; Mardröm börjar där Svår tar slut och går upp till växlande slutledningskedjor. De två nivåerna skiljs åt av en teknisk gräns, inte av antalet givna siffror.\"],\"evANQd\":[\"Kedje- och färgläggningstekniker: X-Chain, XY-Chain, enkel färgläggning och AIC.\"],\"f0OFpM\":[\"<0>Helvete.</0> Stannar alltid av på kedjor och AIC och kräver alltid en tvingande kedja, hämtad från ett inbyggt, verifierat urval.\"],\"fRl01D\":[\"Sudoku att skriva ut\"],\"fUYszb\":[[\"PRINTABLE_BOOKLET_SIZE\"],\" sudokun, utskrivna \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" per sida, med en fullständig lösningsdel.\"],\"fY_UvT\":[\"Det här är häftet att skriva ut för en kort daglig vana snarare än en lång sittning: stoppa det i ett anteckningsblock, lös ett rutnät i taget, och det finns aldrig någon kandidat att skriva ner eller något par att hålla reda på längs raden. Det passar också ett klassrum som introducerar reglerna för första gången, eftersom en hel klass kan avsluta ett sudoku på samma korta stund utan att någon fastnar på en skärning de ännu inte lärt sig. Upplägget med \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" per sida lämnar ändå varje rutnät tillräckligt stort för att skriva i bekvämt, även med ett barns handstil, och facit längst bak gör att en lärare aldrig behöver lösa bladet själv för att kontrollera det.\"],\"fiJRay\":[\"Minst ett <0>pekande par</0>, en <1>block-rad-reduktion</1> eller ett naket eller dolt par, ovanpå de singlar som de lättare häftena redan använder. Inget kräver en fisk, en wing eller en kedja.\"],\"g4WRV6\":[[\"hellCorpusSize\"],\" verifierade sudokun med \",[\"HELL_CORPUS_MINIMUM_GIVEN_COUNT\"],\" till \",[\"HELL_CORPUS_MAXIMUM_GIVEN_COUNT\"],\" givna siffror, hämtade från tdokus katalog med 17 givna siffror och magictours lista top1465 i stället för att genereras på nytt.\"],\"g5Fk5U\":[\"Svår\"],\"gJOrtn\":[\"Svårighetsnivåer\"],\"gh-p06\":[[\"clueCount\"],\" givna siffror av 81 rutor, garanterat att stanna av på singlar och ge vika för en skärning eller en delmängd.\"],\"gmWGv_\":[\"En kedja har ingen fast form, och därför hjälper det mer att markera den med blyerts här än på de lättare nivåerna.\"],\"gqWp2B\":[\"En kedja har ingen fast form: den byggs länk för länk, och det enda sättet att hålla reda på den är att skriva ner den. På papper kan du markera varje stark och svag länk allteftersom, följa växlingen till andra änden och direkt se vilka rutor båda ändarna ser. Det är verkligt omständligt på en telefonskärm som man måste scrolla. Det är också i det här häftet som en felaktig eliminering gör störst skada: stryker du en kandidat som borde ha stannat kvar blir varje länk efter den ohållbar, så se lösningssidorna som en riktig kontrollpunkt snarare än en formalitet.\"],\"h4IqRM\":[\"Känns det bekvämt att hitta skärningar och delmängder? Gå upp till <0>Svår sudoku</0>, där en fisk eller en wing alltid krävs, eller backa till <1>Lätt sudoku</1> för att repetera singlar. Föredrar du papper? Ladda ner <2>häftet med sudoku att skriva ut på nivån Medel</2>. Bläddra bland <3>teknikindexet</3>, <4>guiden för hur man spelar</4>, alla nivåer på sidan <5>Svårighetsnivåer för sudoku</5>, eller gå till <6>startsidan</6>.\"],\"h6WxWJ\":[\"Bra för en avslappnad lösning\"],\"h7hJl_\":[\"Hur svåra de här sudokuna är\"],\"hw66JY\":[\"Sudoku 1 från häftet Lätt, ett av \",[\"PRINTABLE_BOOKLET_SIZE\"],\" i PDF:en.\"],\"i0qMbr\":[\"Startsida\"],\"i7-8lN\":[\"Teknikmedvetna ledtrådar som namnger exakt vilket lösningsmönster som gäller, inte bara nästa siffra\"],\"iDOJbu\":[\"En fisk sträcker sig över hela rader eller kolumner på en gång, vilket är lättare att följa om du markerar en siffras återstående platser nedåt i en utskriven kolumn än om du scrollar på en skärm. Wings kräver det motsatta perspektivet – några bivalenta rutor som man ser med en blick.\"],\"iEH6te\":[\"<0>Dold singel</0> – en siffra som bara passar i en ruta i en enhet.\"],\"iggj45\":[\"Hur svårt är lätt sudoku?\"],\"ippIMU\":[\"De extra tomma rutorna jämfört med Nybörjare räcker för att rutnätet slutar fyllas i av enbart <0>sista lediga rutor</0>. När de uppenbara placeringarna tar slut lämnar ett lätt sudoku alltid minst en ruta där resonemang med dold singel är den enda vägen framåt – kontrollera varje enhets saknade siffror mot var de fortfarande lagligt kan stå, i stället för att läsa kandidater direkt från en enskild ruta. Suuudokuuus teknikmotor prövar dold singel som tredje teknik, direkt efter sista lediga rutan och <1>naken singel</1>, och ett sudoku som bedöms som Lätt behöver aldrig gå längre än så: inga pekande par, inga delmängder, ingenting som kräver att du håller mer än en enhet i huvudet åt gången. Gapet mellan nivåerna är litet med avsikt – det är exakt en teknik brett.\"],\"iu7tUI\":[\"Sökväg\"],\"iuw_bf\":[\"Svårighetsbedömning\"],\"iyTmPq\":[\"Varje namngiven teknik är ett snabbare sätt att hålla reda på samma överlappning mellan rad, kolumn och block över många rutor på en gång.\"],\"j2fzAU\":[\"SE-bedömningarna är de värden som oberoende bedömare och lösarvärlden publicerar. Suuudokuuus egen bedömare rapporterar \",[\"SE_RATING_CEILING\"],\" med en takflagga för allt som är svårare än så, så den tar inte fram någon egen siffra för de här sudokuna.\"],\"j2t1NI\":[\"Varje nivå länkar till en egen sida med en spelbar förhandsvisning och de ärliga fakta om svårighetsgraden från vår <0>guide om sudokuns svårighetsbedömning</0>. Själva PDF:en kräver bara en skrivare.\"],\"jFRHhT\":[\"<0>Oändlighet</0> – \",[\"infinityCorpusSize\"],\" av de svåraste sudokun som någonsin publicerats, valda efter sin publicerade SE-bedömning på \",[\"infinityLowestRating\"],\" till \",[\"infinityHighestRating\"],\" snarare än efter teknikband, och bortom räckvidden för varje teknik i stegen.\"],\"jJ8CSk\":[\"Vårt urval på \",[\"sampleSize\"],\" svåra sudokun mäter SE \",[\"seRatingRange\"],\".\"],\"jMk3uh\":[\"Börja inte med att leta efter den svåraste rutan. Börja med att leta efter de enklaste möjliga placeringarna, för när du tar dem först blir varje ruta därefter också lättare.\"],\"jP5seF\":[\"Lär dig teknikerna i svårighetsordning i stället för att lära dig alla mönster på en gång. <0>Teknikindexet för sudoku</0> listar dem från sista lediga rutan upp till delmängdsmönstren, var och en med ett genomarbetat exempel.\"],\"jmetfY\":[\"Behöver man blyertsmarkeringar i lätta sudokun?\"],\"juLzrc\":[\"Lätt är den första nivån där Suuudokuuu förväntar sig en riktig, om än mild, lösning. Ett lätt sudoku har \",[\"clueCount\"],\" givna siffror av 81 rutor, några färre än Nybörjare. Sista lediga rutan och nakna singlar klarar fortfarande det mesta av rutnätet, men aldrig allt: minst en ruta kräver alltid en <0>dold singel</0>, där en siffra bara passar i en ruta i en rad, kolumn eller block trots att rutan fortfarande visar andra kandidater. Det enda extra mönstret är hela steget upp från Nybörjare till Lätt, och det är en garanti och inte en tendens: ett sudoku som en lösare med enbart sista lediga rutan och nakna singlar kan avsluta förkastas som för lätt för nivån, och ett sudoku som kräver något mer än den dolda singeln förkastas som för svårt.\"],\"jwpEc6\":[\"När de enkla placeringarna tar slut blir det nödvändigt att hålla reda på kandidaterna för hand. En kandidat, ibland kallad blyertsmarkering, är en siffra som en ruta fortfarande lagligt kan innehålla utifrån vad dess rad, kolumn och block redan innehåller. Att skriva in varje kandidat i en ruta – på papper som små siffror i hörnet, eller med anteckningsläget i en app – förvandlar ett sudoku som ser fastlåst ut till ett där mönster blir synliga: par, trippler och kvadrupplar av kandidater som upprepas över en enhet är precis det som tekniker som nakna par och dolda par är gjorda för att upptäcka. Hela metoden för varje mönster finns i <0>teknikindexet för sudoku</0>, och varje term som används i de här guiderna definieras i <1>sudokuordlistan</1>.\"],\"kFGAW9\":[\"Gör få givna siffror att sudokun blir svåra?\"],\"kV-GNp\":[\"<0>Medel</0> – \",[\"mediumClueCount\"],\" givna siffror, garanterat att stanna av på singlar och ge vika för skärningar och delmängder.\"],\"kbLXsu\":[\"Lösningar finns på de sista sidorna\"],\"kc2u3T\":[\"Stryk kandidater ruta för ruta\"],\"lAIHWp\":[\"<0>Svår</0> – \",[\"hardClueCount\"],\" givna siffror, garanterat att stanna av på delmängder och ge vika för fisk- och wing-mönster.\"],\"lDdTS6\":[\"Vanliga frågor om medelsvårt sudoku att skriva ut\"],\"lINilK\":[\"PDF:en inleds med en försättssida som anger antalet sudokun och sidor, fortsätter med \",[\"PRINTABLE_BOOKLET_SIZE\"],\" sudokun utskrivna \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" per sida och avslutas med varje löst rutnät på de sista sidorna, så att svaren aldrig ligger bredvid ett olöst sudoku. Varje rutnät är ritat med vektorlinjer och PDF-standardtypsnittet Helvetica, så det förblir skarpt i vilken utskriftsstorlek som helst och beror aldrig på en skannad bild. Vårt publicerade urval på \",[\"sampleSize\"],\" sudokun för nybörjare mäter SE \",[\"seRatingRange\"],\" – siffror som <0>guiden om sudokuns svårighetsbedömning</0> mäter direkt i stället för att anta.\"],\"lPXkj-\":[\"Kan jag skriva ut det här häftet för nybörjare med stor stil?\"],\"lQAsJI\":[\"<0>Kolumnregeln.</0> Var och en av de nio kolumnerna ska innehålla siffrorna 1 till 9 exakt en gång vardera.\"],\"laMpeD\":[\"Mardröm\"],\"llBUQM\":[\"Fungerar helt offline när den är installerad, på iOS, Android och webben\"],\"lxRnL8\":[\"<0>Blockregeln.</0> Vart och ett av de nio 3×3-blocken ska innehålla siffrorna 1 till 9 exakt en gång vardera.\"],\"lzXj7Z\":[\"Varje sudoku i det här häftet kräver en tvingande kedja: inget går att avsluta med de tekniker som Mardröm tillåter, och vart och ett är hämtat från vårt inbyggda och oberoende verifierade urval för Helvete i stället för att genereras på nytt. Vårt publicerade urval på \",[\"sampleSize\"],\" sudokun mäter nivån till SE \",[\"seRatingRange\"],\", med <0/> som det vanligaste svåraste steget. Se <1>guiden om sudokun med 17 givna siffror</1> för varför antalet givna siffror inte är det som gör dem svåra.\"],\"mDD4iI\":[\"Ja, utan konto och utan vattenstämpel, och varje sudokus lösta rutnät ingår längst bak.\"],\"mOCJOb\":[\"Har du klarat några sudokun på Mardröm? <0>Sudoku på nivån Helvete</0> är den sista nivån, där varje sudoku kräver en tvingande kedja. Gå tillbaka till <1>Svår sudoku</1> om fiskar och wings fortfarande känns osäkra. Föredrar du papper? Ladda ner <2>häftet med sudoku att skriva ut på nivån Mardröm</2>. Bläddra bland <3>teknikindexet</3>, <4>guiden för hur man spelar</4>, alla nivåer på sidan <5>Svårighetsnivåer för sudoku</5>, eller gå till <6>startsidan</6>.\"],\"mVu64h\":[\"Sudokun för nybörjare har \",[\"clueCount\"],\" givna siffror och garanteras gå att avsluta enbart med sista lediga rutan och nakna singlar.\"],\"m_1uBm\":[\"Dagens sudoku\"],\"mbw3Zs\":[\"Vilka svårighetsnivåer finns det?\"],\"mdr9O2\":[[\"PRINTABLE_BLANK_GRID_PAGE_COUNT\"],\" sidor\"],\"mf-vQH\":[[\"newbieClueCount\"],\" givna siffror, löses enbart med sista lediga rutan och nakna singlar. Se <0>sidan för sudoku för nybörjare</0> om du vill spela det digitalt.\"],\"mqvuZQ\":[\"Lär dig lösa\"],\"n8c99d\":[\"Sudokulösare\"],\"ngqvTg\":[\"Delbara sudokulänkar och fullständiga repriser av varje lösning\"],\"o83Dls\":[\"Lätta sudokun har \",[\"clueCount\"],\" givna siffror och garanterar minst en dold singel men inget svårare.\"],\"o8ErsC\":[\"Kan ett sudoku ha två lösningar?\"],\"oACpQU\":[\"Guider om svårighetsgrad\"],\"oF5_MF\":[\"Stor textstorlek\"],\"oFKMy-\":[\"Inte redo för kedjor på papper än? Gå tillbaka till <0>häftet med sudoku att skriva ut på nivån Mardröm</0> för samma kedjeresonemang med mer av rutnätet ifyllt, eller till <1>sudoku att skriva ut på nivån Svår</1> för fiskar och wings utan resonemang i kedjelängd, eller spela Helvete på skärmen på <2>sidan för sudoku på nivån Helvete</2>, där samma urval driver varje sudoku. Redo för rekordsudokun? <3>Häftet med sudoku att skriva ut på Oändlighet</3> skriver ut Everest, AI Escargot och andra rekordrutnät.\"],\"oH36ji\":[\"Har sudokun på Oändlighet en unik lösning?\"],\"oQ8R9m\":[\"Måste man gissa i sudokun på nivån Mardröm?\"],\"oSfAuO\":[\"Medelsvår sudoku\"],\"o_ys4H\":[\"Varje sudoku för nybörjare bedöms på SE-skalan (Sudoku Explainer) i samma stund som det skapas. Vårt publicerade urval på \",[\"sampleSize\"],\" sudokun för nybörjare mäter SE \",[\"seRatingRange\"],\" – allra längst ner på en skala som går till 12, och under vad de flesta SE-baserade diagram ens bryr sig om att namnge. Nybörjare finns för att lära ut överlappningen mellan rad, kolumn och block som varje senare teknik bygger på, inte för att testa den. Det uppmätta spannet för den här nivån och alla andra publiceras i vår <0>guide om sudokuns svårighetsbedömning</0>. Se en snabb och felfri lösning på Nybörjare som en bekräftelse på att du är redo för Lätt, inte som ett mått värt att jaga för sin egen skull.\"],\"oc75Be\":[\"Ett välformat sudoku har aldrig det. Om ett sudoku har mer än en giltig lösning anses det trasigt, eftersom logiken då inte längre kan peka ut ett enda svar.\"],\"ohi_6A\":[\"Kontrollera för varje enhet med flera tomma rutor om en siffra som fortfarande saknas i enheten bara passar i en av dem, även om den rutan har andra kandidater också.\"],\"p6O9l-\":[\"Hur många sudokun finns i PDF:en med sudoku på Oändlighet att skriva ut?\"],\"p95wx0\":[\"Sista lediga rutan och singlar som grund, plus pekande par, pekande trippel, block-rad-reduktion och de nakna eller dolda delmängderna upp till kvadrupplar när singlarna tar slut. Minst en av dem krävs alltid, och inget svårare krävs någonsin.\"],\"pDFJMU\":[\"Ladda ner PDF:en, öppna den i valfri PDF-läsare och skriv ut i 100 % skala på papper i formatet US Letter. Varje rutnät är ritat med vektorlinjer och standardtypsnitt för PDF, så det finns inget att rastrera och ingen kvalitetsförlust i någon utskriftsstorlek.\"],\"pIksP6\":[\"Vanliga frågor om sudoku på Oändlighet\"],\"pN5c2M\":[\"Mardröm-sudoku\"],\"pOHwnD\":[\"Vilka tekniker kräver det här häftet med medelsvår sudoku?\"],\"pXows4\":[\"Suuudokuuu har sju svårighetsnivåer: sex som var och en kräver en bredare uppsättning tekniker än den förra, och Oändlighet.\"],\"pe908p\":[\"En given siffra är en siffra som står tryckt på brädet innan du börjar. En kandidat är en siffra som du fortfarande överväger för en tom ruta, utifrån vad dess rad, kolumn och block för tillfället utesluter.\"],\"plp0e4\":[\"Spela sudoku på nivån Mardröm nu\"],\"pu3rE1\":[\"Med \",[\"clueCount\"],\" givna siffror av 81 rutor är det här häftet det första där det lönar sig att ha en blyertspenna. Singlar tar ett medelsvårt rutnät en bit på väg, men varje sudoku i häftet stannar bevisligen av på dem – det var provet varje sudoku måste misslyckas med för att få tryckas här – tills du upptäcker ett <0>pekande par</0> eller en <1>block-rad-reduktion</1>, en skärning mellan ett block och en linje som bara tar bort kandidater och aldrig placerar en siffra direkt. Inget i häftet kräver en fisk, en wing eller en kedja.\"],\"q7QiGX\":[\"Så spelar du\"],\"qcBjCp\":[\"<0>Mardröm</0> – \",[\"nightmareClueCount\"],\" givna siffror, garanterat att stanna av på wings och ge vika för kedjor och färgläggning.\"],\"qiqtfW\":[\"Spela medelsvår sudoku nu\"],\"qrmik6\":[[\"PRINTABLE_LARGE_PRINT_SIZE\"],\" sudokun\"],\"qwJuVW\":[\"Sidfot\"],\"qyiPQ_\":[\"Lätt är häftet man tar fram när man vill få ett sudoku färdigt utan att behöva fundera hårt – på tåget, på en kaffepaus eller som nedvarvning före sänggåendet. Varje slutsats går fortfarande att läsa av direkt på brädet i stället för i ett kandidatrutnät, så det finns sällan någon anledning att skriva kandidater i marginalen; den dolda singeln kräver att du skannar en hel enhet i stället för en enda ruta, vilket är en ändring av vana och inte av svårighetsgrad. Det gör det till en naturlig storlek att skriva ut flera av på en gång och jobba sig igenom en liten hög under en vecka, eftersom inget enskilt sudoku kräver den koncentration som ett medelsvårt eller svårt rutnät gör.\"],\"r2FUkM\":[\"Spela det här sudokut här\"],\"r4WJmT\":[\"Sudokutekniker\"],\"r7ajsb\":[\"Ingen reklam, inget konto och ingen spårning i spelet, varken på webben eller i appen\"],\"r8BZnz\":[\"Behöver jag penna och papper för att lösa sudoku?\"],\"rFkWoz\":[\"Nej. Varje sudoku som Suuudokuuu genererar kontrolleras för en unik lösning när det skapas, så ingen ruta kräver någonsin en gissning – och de inbyggda sudokuna på Helvete korskontrolleras dessutom av två oberoende lösningsalgoritmer, en exakt täckningslösare med Dancing Links och en bitmasklösare, innan de levereras. Ett läge som ser tvetydigt ut behöver bara en teknik som ännu inte prövats.\"],\"rISE1w\":[\"Vilka tekniker behöver jag för medelsvår sudoku?\"],\"rUmdf8\":[\"Är PDF:en med svårt sudoku att skriva ut gratis?\"],\"rUv2wg\":[\"Även källnivån för PDF:en med stor stil, med ett urval på \",[\"PRINTABLE_LARGE_PRINT_SIZE\"],\" sudokun.\"],\"rcYOQY\":[\"Minst en kedje- eller färgläggningsteknik – fiskar på <0>swordfish</0>-nivå och wings på <1>XY-Wing</1>-nivå räcker inte på egen hand – ovanpå varje fisk och wing som nivån Svår redan kräver.\"],\"rgh2Sh\":[\"Vårt urval på \",[\"sampleSize\"],\" sudokun på Mardröm mäter SE \",[\"seRatingRange\"],\".\"],\"rhRptr\":[\"Det är ett riktigt steg upp från Lätt, men varje teknik som krävs fungerar ändå inom ett enda block eller en enda linje i taget – de längre fisk- och kedjemönstren börjar först på Svår och uppåt.\"],\"rjZpLn\":[\"Lär dig\"],\"rtx2YX\":[[\"easyClueCount\"],\" givna siffror, och varje sudoku kräver minst en dold singel, aldrig mer. Se <0>sidan för lätt sudoku</0> om du vill spela det digitalt.\"],\"sAlGDx\":[\"Gratis, öppen källkod, ingen reklam\"],\"sMgCJW\":[\"Ett sudoku som kräver en dold singel eller något svårare förkastas och genereras om, och märks aldrig som Nybörjare.\"],\"sYhvIH\":[\"<0>Oändlighet.</0> De svåraste sudokun som någonsin publicerats, som Everest och AI Escargot, valda efter sin publicerade bedömning snarare än efter teknikband – se <1>sidan för Oändlighet</1>.\"],\"sf_Uq_\":[\"Vårt urval på \",[\"sampleSize\"],\" sudokun för nybörjare mäter SE \",[\"seRatingRange\"],\".\"],\"sgcKNN\":[\"Varje sudokuregel är egentligen samma villkor tillämpat på tre olika slags enheter. Lär dig villkoret en gång så kan du redan alla tre reglerna.\"],\"sjwplg\":[\"Varje häfte nedan är en gratis PDF med sudoku att skriva ut, byggd från samma sudokukällor som appen spelar – dess generator och teknikdetektorer, och för Helvete och Oändlighet dess inbyggda, verifierade urval. Välj en svårighetsgrad för ett häfte med \",[\"PRINTABLE_BOOKLET_SIZE\"],\" sudokun med lösningar på de sista sidorna, eller ta uppsättningen med stor stil eller ett tomt sudokurutnät nedan. Ingen registrering, ingen reklam, ingen vattenstämpel.\"],\"ssPRl9\":[\"Suuudokuuus svåraste nivå: \",[\"infinityCorpusSize\"],\" av de svåraste sudokun som någonsin publicerats, vart och ett med en publicerad SE-bedömning på \",[\"minimumRatingLabel\"],\" eller mer, spelbara gratis utan reklam.\"],\"svA7xQ\":[\"Redo för ett sudoku som kräver en idé till? Gå upp till <0>Lätt sudoku</0>, som lägger till den dolda singeln ovanpå allt här. Föredrar du papper? Ladda ner <1>häftet med sudoku för nybörjare att skriva ut</1>, eller se guiden <2>sudoku för seniorer</2> för alternativ med stor stil och bättre komfort. Bläddra bland hela <3>teknikindexet</3> eller <4>guiden för hur man spelar</4>, eller gå tillbaka till <5>startsidan</5> och se alla sju nivåer på sidan <6>Svårighetsnivåer för sudoku</6>.\"],\"tHJbOh\":[\"Är Oändlighet svårare än Helvete?\"],\"tK6SRc\":[\"Varje sudoku kräver en tvingande kedja, hämtad från ett inbyggt och oberoende verifierat urval av sudokun med \",[\"HELL_CORPUS_MINIMUM_GIVEN_COUNT\"],\" till \",[\"HELL_CORPUS_MAXIMUM_GIVEN_COUNT\"],\" givna siffror.\"],\"tYB68O\":[\"Sudoku 1 från häftet Oändlighet, ett av \",[\"PRINTABLE_BOOKLET_SIZE\"],\" i PDF:en.\"],\"tc4WHX\":[\"Betyder färre givna siffror alltid ett svårare sudoku?\"],\"thMLRg\":[\"Svår slutar vid W-Wing – ett sudoku som står emot alla fiskar och wings får i stället betyget Mardröm.\"],\"uFeI93\":[\"Varje spel blandar om rutnätet, så ett välkänt rekordsudoku ser aldrig likadant ut två gånger.\"],\"uJerz5\":[\"Suuudokuuu graderar sina sudokun på en stege med sex nivåer, från Nybörjare till Helvete, och varje nivå definieras av två konkreta fakta snarare än en marknadsföringsetikett: hur många givna siffror rutnätet börjar med, och vilka namngivna lösningstekniker nivån garanterat kräver. Varje nytt sudoku bedöms dessutom på SE-skalan (Sudoku Explainer) i samma stund som det skapas, av samma bedömningspaket med öppen källkod som <0>guiden om sudokuns svårighetsbedömning</0> använder för att publicera det uppmätta bandet och SE-spannet för varje nivå på stegen nedan. Ovanför stegen ligger <1>Oändlighet</1>, ett kurerat urval av rekordsudokun som bär de bedömningar som oberoende bedömare publicerar, eftersom de når förbi toppen av vår egen bedömningsskala.\"],\"uy5vQS\":[\"Skriv eller klistra in rutnätet i den <0>stegvisa sudokulösaren</0> så namnger den varje drag – Dold singel, Naket par, X-Wing – i stället för att bara fylla i brädet. Den kontrollerar först att ditt sudoku har exakt en lösning, och den körs helt i din webbläsare.\"],\"uyJsf6\":[\"Om\"],\"v1_ToA\":[\"Skärningar och par hittas genom att markera alla återstående kandidater i en enhet, så upplägget lämnar utrymme i varje ruta just för de blyertsmarkeringarna.\"],\"vAJFgP\":[\"Bra för en första sudokuvana\"],\"vEHxJQ\":[\"Svårighetsnivåer för sudoku\"],\"vLhN57\":[\"Vårt urval på \",[\"sampleSize\"],\" svåra sudokun mäter SE (Sudoku Explainer) \",[\"seRatingRange\"],\" – mitt i det spann som lösarvärlden förknippar med fisk- och wing-mönster, och långt under kedjeterritoriet över 7. Det vanligaste svåraste steget är <0/>, och det svåraste något i urvalet nådde är <1/>. Det är här tillfälliga lösare börjar ta fram en ledtråd: fiskar och wings är lätta att beskriva och verkligen svåra att se på ett pågående bräde, så räkna med en märkbart längre och mer eftertänksam lösning än Medel kräver. Se <2>guiden om sudokuns svårighetsbedömning</2> för alla data per nivå.\"],\"vNl4Yu\":[\"Lätt börjar på \",[\"clueCount\"],\" givna siffror, sex färre än Nybörjare, och lägger till exakt en teknik: varje sudoku i det här häftet kräver minst en <0>dold singel</0>, och inget kräver något svårare. Just det enda extra mönstret gör det till häftet man skriver ut för en avslappnad lösning på kaffepausen snarare än som läromedel. Det är också källnivån för vår PDF med stor stil, med ett urval på \",[\"PRINTABLE_LARGE_PRINT_SIZE\"],\" sudokun för läsare som vill ha större rutor.\"],\"vXIe7J\":[\"Språk\"],\"vbOpg_\":[\"Därför \",[\"SITE_NAME\"]],\"viJ4-_\":[\"Vårt urval på \",[\"sampleSize\"],\" sudokun på Helvete mäter SE \",[\"hellSeRatingRange\"],\".\"],\"vlNS-q\":[\"Nybörjare är Suuudokuuus nybörjarnivå, den mildaste tänkbara introduktionen till rutnätet. Ett sudoku för nybörjare börjar med \",[\"clueCount\"],\" av de 81 rutorna redan ifyllda. Varje återstående ruta kan hittas med de två enklaste slutsatserna i spelet: en <0>sista ledig ruta</0>, där en enhet bara har en enda tom ruta kvar, och en <1>naken singel</1>, där rutans rad, kolumn och block tillsammans redan svarar för åtta av de nio siffrorna. Det är ingen beskrivning av ett typiskt sudoku för nybörjare – det är regeln som generatorn tillämpar: en kandidat godkänns som Nybörjare först när en lösare som är begränsad till sista lediga rutan och nakna singlar har avslutat den. Inga blyertsmarkeringar, ingen elimineringslogik och ingen gissning krävs någonsin.\"],\"voLlG5\":[\"Så börjar du lösa ett sudoku\"],\"vsge_o\":[\"Ny på sudoku?\"],\"vvCT_r\":[\"Vart du kan gå härnäst\"],\"vwz0Q4\":[\"PDF på \",[\"fileSizeKilobytes\"],\" KB, US Letter\"],\"wIwe3l\":[\"Så byggs stegen\"],\"wT9V53\":[\"Medel är nivån där Suuudokuuu börjar kräva blyertsmarkeringar. Ett medelsvårt sudoku har \",[\"clueCount\"],\" givna siffror av 81 rutor, och enbart singlar räcker bevisligen aldrig till: varje sudoku på nivån har kontrollerats mot en lösare med enbart singlar och förkastats om den lösaren tog sig igenom. När sista lediga rutan och singlarna tar slut stannar sudokut av tills du upptäcker en skärning – en siffra som är begränsad till överlappningen mellan ett block och en linje – eller ett par som är låsta till varandra. <0>Pekande par</0>, <1>pekande trippel</1> och <2>block-rad-reduktion</2> täcker skärningarna; <3>nakna par</3> och <4>dolda par</4> täcker det minsta delmängdsmönstret.\"],\"xI2Au1\":[\"Sudoku 1 från häftet Svår, ett av \",[\"PRINTABLE_BOOKLET_SIZE\"],\" i PDF:en.\"],\"xRTkBI\":[\"Oändlighet\"],\"xTziZu\":[[\"PRINTABLE_BOOKLET_SIZE\"],\" sudokun fördelade på \",[\"PRINTABLE_BOOKLET_PAGE_COUNT\"],\" sidor, \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" per sida, med de lösta rutnäten längst bak.\"],\"xYaf-9\":[\"Är Helvete svårare än Mardröm?\"],\"xkW-Mi\":[\"Varför lämnar det här häftet mer plats runt varje siffra?\"],\"xs4NvR\":[\"Är \",[\"SITE_NAME\"],\" gratis?\"],\"y-GOTe\":[\"Titta därefter på en enskild tom ruta och stryk varje siffra som redan finns i dess rad, kolumn och block. Om bara en siffra återstår är det en <0>naken singel</0>, som kan placeras direkt. Om en ruta fortfarande har flera kandidater kvar, kontrollera om någon av dem inte kan stå någon annanstans i samma enhet – det är en <1>dold singel</1>, och den är lika säker att placera. Tillsammans löser de här två mönstren det mesta av ett lätt sudoku utan något djupare resonemang.\"],\"yDLr5P\":[\"Sudoku med stor stil\"],\"yNzy3T\":[\"Vårt urval på \",[\"sampleSize\"],\" medelsvåra sudokun mäter SE \",[\"seRatingRange\"],\", och \",[\"singlesOnlyPuzzleCount\"],\" av \",[\"sampleSize\"],\" avslutades med enbart singlar – det här är den första nivån där det talet är noll per konstruktion. Det vanligaste svåraste steget i urvalet är <0/>, och det svåraste något nådde är <1/>. Spelare som läser blyertsmarkeringar flytande klarar ett medelsvårt sudoku märkbart snabbare än spelare som förlitar sig på att hålla kandidaterna i huvudet, och de kommer att upptäcka att det här är den första nivån där det verkligen lönar sig att skriva ner kandidater. Alla data per nivå finns i vår <2>guide om sudokuns svårighetsbedömning</2>.\"],\"y_3zNL\":[\"Sista lediga rutan och nakna singlar klarar fortfarande det mesta av rutnätet; den dolda singeln är det enda som tillkommer jämfört med Nybörjare.\"],\"yjTW_5\":[\"Vilka tekniker behöver jag för nivån Helvete?\"],\"yy8xD2\":[\"Själva rutnätet ändras aldrig: nio rader, nio kolumner och nio block, åttioen rutor sammanlagt. Det som ändras från sudoku till sudoku är bara vilka rutor som börjar ifyllda och vilka siffror de innehåller, och det är den startuppsättningen av givna siffror som avgör hur mycket logik som krävs för att nå den enda giltiga lösningen.\"],\"z0P0h9\":[\"Vårt urval på \",[\"sampleSize\"],\" sudokun på Helvete mäter SE (Sudoku Explainer) \",[\"hellSeRatingRange\"],\", med <0/> som det vanligaste svåraste steget och <1/> som det svåraste steg något i urvalet nådde. Se upp med att läsa antalet givna siffror som orsaken: samma urval placerar <2>Mardröm</2> på SE \",[\"nightmareSeRatingRange\"],\" med \",[\"nightmareClueCount\"],\" givna siffror, och vissa sudokun på Helvete börjar med fler givna än så. Den här nivån byggdes tidigare enbart av sudokun med 17 givna siffror, och den bedömdes inte som svårare än Mardröm; att i stället välja efter den nödvändiga tekniken är det som skiljer de två åt. Vår <3>guide om givna siffror kontra svårighetsgrad</3> går igenom det resonemanget ordentligt, och <4>bedömningsguiden</4> publicerar tabellerna per nivå.\"],\"zGCYA8\":[\"Kan jag spela AI Escargot och Everest här?\"],\"zX6n8C\":[\"Rekordsudokun som Everest och AI Escargot, utskrivna precis som de ursprungligen publicerades. Se <0>sidan för sudoku på Oändlighet</0> om du vill spela dem digitalt.\"],\"zaRGXY\":[\"Tomt sudokurutnät\"],\"zdhNJO\":[\"Vanliga frågor om medelsvår sudoku\"],\"zu-XZL\":[\"Lätt sudoku\"],\"zuuvDj\":[[\"PRINTABLE_BOOKLET_SIZE\"],\" rekordsudokun, utskrivna \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" per sida, med en fullständig lösningsdel.\"]}")as Messages;